import {find,isLocked} from '../document/model.js';import {evaluated,setProperty,enableTrack} from '../animation/evaluate.js';import {escape} from '../renderer/svg.js';import {shadowFields} from '../scene/shadow.js';import {showGraph} from '../timeline/graph.js';
export function showLayerMenu(a,id=a.selected[0]){
 const n=find(a.doc,id);if(!n)return a.toast('Select a layer first.');a.pause();a.properties.flush();a.selected=[id];a.render();const v=evaluated(n,a.time),locked=isLocked(a.doc,id);
 let applied=false,preview=false;
 const limits=key=>key==='shadowOpacity'?[0,1,.05]:key==='shadowBlur'?[0,200,1]:[-4096,4096,1];
 const field=(key,label)=>{const [min,max,step]=limits(key);return `<label>${label}<input name="${key}" type="${key==='shadowColor'?'color':'number'}" value="${v[key]}" step="${step}" ${key==='shadowColor'?'':`min="${min}" max="${max}"`}>${key==='shadowColor'?'':`<input type="range" data-shadow-slider="${key}" aria-label="${label} slider" min="${key==='shadowX'||key==='shadowY'?-200:min}" max="${key==='shadowX'||key==='shadowY'?200:max}" step="${step}" value="${v[key]}">`}</label>`;};
 const read=form=>Object.fromEntries(Object.keys(shadowFields).map(prop=>{const value=prop==='shadowColor'?form.get(prop):Number(form.get(prop)),[min,max]=limits(prop);if(prop==='shadowColor'?!/^#[0-9a-f]{6}$/i.test(value):!Number.isFinite(value)||value<min||value>max)throw Error('Choose a valid '+shadowFields[prop].toLowerCase()+'.');return [prop,value];}));
 const d=a.dialog('Layer · '+escape(n.name),`<div class="layer-menu-actions"><button data-layer-graph>⌁ Graph editor</button><button data-layer-properties>All properties</button></div>${n.reference?'<label class="shadow-toggle"><input data-reference-export type="checkbox" '+(n.exportIncluded?'checked':'')+'> Include reference frames in exports</label><label>Reference opacity<input data-reference-opacity type="range" min=".05" max="1" step=".05" value="'+n.opacity+'"></label><p class="subtle">Baked reference frames are locked for tracing. Visibility and opacity remain adjustable.</p>':''}${n.reference?'<p>Use the sequencer block boundaries to trim this reference.</p>':n.type==='group'?'<p>Choose a shape inside this group to add a shadow.</p>':`<form><fieldset ${locked?'disabled':''}><legend>Drop shadow</legend><label class="shadow-toggle"><input name="shadowEnabled" type="checkbox" ${v.shadowEnabled?'checked':''}> Enable drop shadow</label><div class="dialog-grid">${Object.entries(shadowFields).map(([key,label])=>field(key,label)).join('')}</div><p class="subtle">Offsets and blur use shape pixels. Shadow follows the shape and exports with it.</p><div class="dialog-actions"><button type="button" data-shadow-keys>◇ Animate shadow</button><button type="button" data-close>Cancel</button><button type="submit" class="primary">Apply shadow</button></div></fieldset></form>`}`, (form,dialog)=>{
  const values=read(form);a.mutate('Drop shadow',()=>{n.shadowEnabled=form.has('shadowEnabled');for(const [prop,value] of Object.entries(values))setProperty(n,prop,value,a.time);});applied=true;dialog.close();
 });
 d.querySelector('[data-reference-export]')?.addEventListener('change',e=>a.mutate('Reference export visibility',()=>n.exportIncluded=e.target.checked));d.querySelector('[data-reference-opacity]')?.addEventListener('change',e=>a.mutate('Reference opacity',()=>n.opacity=Number(e.target.value)));const discard=()=>{if(preview&&!applied){a.history.cancel();preview=false;a.render();}};
 d.querySelector('[data-layer-graph]').onclick=()=>{discard();d.close();showGraph(a,id);};d.querySelector('[data-layer-properties]').onclick=()=>{discard();d.close();document.querySelector('.inspector').classList.add('open');};
 d.querySelector('[data-shadow-keys]')?.addEventListener('click',()=>a.safe(()=>{if(locked)return;const values=read(new FormData(d.querySelector('form')));a.mutate('Animate shadow',()=>{n.shadowEnabled=true;for(const [prop,value] of Object.entries(values)){if(!n.tracks[prop]?.length)n[prop]=v[prop];enableTrack(n,prop,a.time,a.ease);setProperty(n,prop,value,a.time);}});applied=true;d.close();showGraph(a,id,'shadowX');}));
 d.addEventListener('input',e=>{if(locked||!e.target.closest('form'))return;const slider=e.target.dataset.shadowSlider;if(slider)d.querySelector(`[name="${slider}"]`).value=e.target.value;else if(e.target.name&&e.target.type==='number'){const range=d.querySelector(`[data-shadow-slider="${e.target.name}"]`);if(range)range.value=e.target.value;}try{const form=new FormData(d.querySelector('form')),values=read(form);a.history.begin();preview=true;n.shadowEnabled=form.has('shadowEnabled');for(const [prop,value] of Object.entries(values))setProperty(n,prop,value,a.time);a.renderStage();}catch{}});
 d.addEventListener('close',discard,{once:true});
}
